function buildOrder(n, deps) {
  const next = Array.from({ length: n }, () => [])
  const waiting = new Array(n).fill(0)
  for (const [a, b] of deps) {
    next[a].push(b)
    waiting[b]++
  }
  const heap = []
  const push = value => {
    heap.push(value)
    let i = heap.length - 1
    while (i > 0) {
      const parent = (i - 1) >> 1
      if (heap[parent] <= heap[i]) break
      ;[heap[parent], heap[i]] = [heap[i], heap[parent]]
      i = parent
    }
  }
  const pop = () => {
    const top = heap[0]
    const last = heap.pop()
    if (heap.length) {
      heap[0] = last
      let i = 0
      while (true) {
        const l = 2 * i + 1
        const r = l + 1
        let m = i
        if (l < heap.length && heap[l] < heap[m]) m = l
        if (r < heap.length && heap[r] < heap[m]) m = r
        if (m === i) break
        ;[heap[m], heap[i]] = [heap[i], heap[m]]
        i = m
      }
    }
    return top
  }
  for (let v = 0; v < n; v++) if (waiting[v] === 0) push(v)
  const order = []
  while (heap.length) {
    const v = pop()
    order.push(v)
    for (const w of next[v]) {
      if (--waiting[w] === 0) push(w)
    }
  }
  return order.length === n ? order : []
}
